def create_board(rows, cols, row_black_segments, col_black_segments):
    board = [['.' for _ in range(cols)] for _ in range(rows)]
    for row, black_segments in enumerate(row_black_segments):
        for segment in range(black_segments + 1):
            start = segment
            while start < len(row_black_segments) and row_black_segments[start] >= segment:
                board[row][start] = '*'
                start += 1
    for col, black_segments in enumerate(col_black_segments):
        for segment in range(black_segments + 1):
            start = segment
            while start < len(col_black_segments) and col_black_segments[start] >= segment:
                board[start][col] = '*'
                start += 1
    return board

