from collections import defaultdict

def find_path(graph, start, goal, visited, path):
    path.append(goal)
    if len(path) == len(graph) + 1:
        return path
    for neighbor in graph[goal]:
        if neighbor not in visited:
            visited.add(neighbor)
            result = find_path(graph, start, neighbor, visited, path)
            if result is not None:
                return result
    path.pop()
    return None

def solve(n, m, corridors):
    graph = defaultdict(list)
    matrix = [[0]*n for _ in range(n)]
    for u, v in corridors:
        matrix[u-1][v-1] = 1
        matrix[v-1][u-1] = 1

    visited = set()
    visited.add(0)
    for i in range(n):
        result = find_path(graph, None, i, visited, [i])
        if result is not None:
            return result[:-1]
    return [-1]

