def merge_lists(s_b, A, s_a, B):
    s = []
    a_index, b_index = 0, 0
    inversions = 0

    while a_index < len(A) or b_index < len(B):
        a_next = A[a_index] if (a_index < len(A)) else '1'
        b_next = B[b_index] if (b_index < len(B)) else '0'

        if (s_b <= a_next and s_a <= b_next):
            match s_b:
                case '0':
                    s.append('0')
                case '1':
                    s.append('1')
        else:
            if s_b == '0':
                inversions += 1                
            s.append(s_b)

        if s_b == '0':
            a_index += 1
        else:
            b_index += 1
        s_b = '1' if s_b == '0' else '0'

