import sys

def fix_flow(graph, s, t):
    m = len(graph)
    f = [float('inf')] * m
    c = [float('inf')] * m
    for u, v, c, f in graph:
        if u == s:
            if f > 0:
                if f < c:
                    f[v-1] = c
        else:
            if v == t:
                if f > 0:
                    if f < c:
                        f[u-1] = c
    total_change = 0
    for u, v, c, f in graph:
        prev_flow = f.copy()
        prev_capacity = c.copy()
        if u == s:
            next_node = v
        else:
            next_node = u
        while next_node != s and next_node != t and next_node != v:
            next_edge = None
            next_capacity = None
            next_flow = None
            for i, neighbor in enumerate(graph):
                if neighbor[0] == next_node:
                    if neighbor[1] == v:
                        next_capacity = neighbor[2]
                        next_flow = neighbor[3]
                    elif neighbor[1] == next_node:
                        next_flow = neighbor[3]
                        next_capacity = neighbor[2]
                    else:
                        pass
            if next_capacity < next_flow and next_capacity > 0:
                if next_capacity >= next_flow and next_capacity < c[i]:
                    f[i] = next_capacity
                    c[i] = next_capacity
                    total_change += min(f[i] - prev_flow[i], 0)
                elif next_capacity > 0 and next_capacity < next_flow:
                    c[i] = next_capacity
                    total_change += min(c[i] - prev_capacity[i], 0)
            else:
                if next_capacity - next_flow == 0:
                    f[i] = min(next_capacity, prev_capacity[i])
                else:
                    total_change += min(next_capacity, prev_capacity[i])
                if next_capacity > next_flow:
                    total_change += abs(next_capacity - next_flow)
                if next_capacity < prev_capacity[i]:
                    total_change += abs(next_capacity - prev_capacity[i])
        if next_node == t:
            break
    return total_change

