def min_ones_after_operations(n, m, rows):
    count_offset = [0] * n
    for row in rows:
        ones = row.count('1')
        zeros = row.count('0')
        num, zero_index = zeros + ones, -1
        if zero_index == -1:
            num, zero_index = ones, -1
        if num < n // 2:
            if not zero_index == -1:
                zero_index = n * num
            zero_index -= ones
        else:
            if zero_index == -1:
                zero_index = 1 * num + n * (n - ones)
            zero_index += ones + 1
        for i in range(n):
            count_offset[i] = zero_index xor (n * i)
    return max(count_offset)

