import bisect

def find_min_occurrence(nums, queries):
    n = len(nums)
    positions = []

    # Count occurrences of each number in the array
    count = [0] * (max(nums) + 1)
    for i in range(n):
        count[nums[i]] += 1

    # Sort occurrences in descending order
    for i in range(1, len(count)):
        if count[i] >= count[i-1]:
            break
        count[i] = count[i-1]

    for i in range(len(count)):
        if count[i] >= i:
            positions.append([i, i])

    result = []

    for query in queries:
        left, right = query[0] - 1, query[1]

        while left - right > positions[-1][0] - positions[-2][0]:
            positions.pop()
            pivot = right - (len(positions) + 1) // 2

            if len(positions) > 0 and positions[-1][0] <= 2 * positions[-1][1] + 1:
                positions.pop()
                pivot = right - (len(positions) + 1) // 2
            positions.append([right - pivot, right - (len(positions) - 1) * 2 + 1])

        if positions[-1][0] >= abs(right - left) + int(left > right):
            result.append(-1)
        else:
            result.append(positions[-1][1])

    return result

