import math

def is_greedy_optimal(coin_values):
    n = len(coin_values)
    dp = [math.inf] * (2**n)
    dp[0] = 0  # Base case: 0 coin is optimal

    for mask in range(1, (1 << n)):
        coins = bin(mask).count('1')
        sum_ = mask.bit_count()
        if coins > sum_:  # If more than half coins can form sum, mark as non-optimal
            dp[mask] = dp[mask & (mask - 1)] + 1
        else:
            max_sum = -1
            for coin in coin_values:
                if (mask & (1 << coin)) > 0:
                    cur_sum = dp[(mask ^ (1 << coin))] + 1
                    if cur_sum < max_sum:
                        max_sum = cur_sum
            dp[mask] = max_sum

    return dp[(1 << n) - 1] != math.inf

def find_smallest_nonoptimal(coin_values):
    n = len(coin_values)
    ans = math.inf
    for i in range(n, -1, -1):
        mask = 1 << i
        if mask > (1 << n - 1):
            continue
        coin_ = coin_values[i]
        copy = mask | (1 << i)
        if bin(copy).count('1') > bin(mask).count('1'):
            ans = min(ans, dp[coin_ - 1])
    return ans if ans != math.inf else -1

coin_values = list(map(int, input().split()))
