import heapq

def find_optimal_path(n, m, corridors):
    # Sort corridors based on their endpoints
    corridors.sort(key=lambda x: (x[0], x[1]))
    opened_corr = [0] * (n + 1)  # Initialize the opened corrc variables

    path_length = 0
    visited = [False] * (n + 1)
    heapq.heappush(opened_corr[1], ((1, None), 0))  # Push starting point
    optimal_path = [0]  # Since the path starts at visited[0], path starts from index 0

    while True:
        # Get the unprocessed corridor with 0 time left
        (from_to, time_left) = heapq.heappop(opened_corr[1])
        if visited[from_to[1]]:
            continue
        visited[from_to[1]] = True
        if from_to[1] == n:
            path_length += time_left        
            optimal_path.append(path_length)
            if from_to[1] in corridors:
                for corr in corridors:
                    if corr == from_to:
                        continue
                    if from_to[1] == corr[0] and not visited[corr[1]]:
                        visited[corr[1]] = True
                    elif from_to[1] == corr[1] and not visited[corr[0]]:
                        visited[corr[0]] = True
                return optimal_path
            else:
                for corr in corridors:
                    if corr[0] not in [from_to[1], from_to[0]] and corr[1] not in [from_to[1], from_to[0]]:
                        continue
                    if visited[from_to[1]]:
                        continue
                    if from_to[0] == corr[0] and not visited[corr[1]]:
                        visited[corr[1]] = True
                        heapq.heappush(opened_corr[1], ((corr[0], corr[1]), time_left + 1))  # Traverse
                        continue
                    if from_to[1] == corr[1] and not visited[corr[0]]:
                        visited[corr[0]] = True
                        heapq.heappush(opened_corr[1], ((from_to[0], corr[0]), time_left + 1))  # Traverse
                        continue
        path_length += time_left
        optimal_path.append(path_length)
        for corr in corridors:
            if corr == from_to:
                continue
