                elif pattern[count].lower() == 'd' and cur_col >= 1 and cur_row == row:
                    cur_col -= 1
                elif pattern[count].lower() == 'l' and cur_col == 0 and cur_row == row:
                    cur_col += 1
                elif pattern[count].lower() == 'r' and cur_col >= 1 and cur_row == row:
                    cur_col += 1

                count += 1
