from collections import defaultdict

def generate_outcomes(initial_population):
    outcomes = []
    pairs = defaultdict(list)

    for i in range(len(initial_population)):
        for j in range(i + 1, len(initial_population)):
            pairs[(initial_population[i], initial_population[j])].append((i, j))

    for (a, b), indices in pairs.items():
        if len(indices) == 1:
            outcomes.append((a, b))
            outcomes.append((b, a))
        else:
            numbers = sorted([subpop[0] - subpop[1] for subpop in indices])
            last_number = numbers[0]
            for number in numbers[1:]:
                outcomes.append(((last_number, i), (number, j)))
                outcomes.append(((number, j), (i, last_number)))
    return outcomes

def calculate_residues(initial_population, n):
    outcomes = generate_outcomes(initial_population)
    hist = [0] * len(outcomes)
    mod = 10**9 + 7

    for subpopulation in initial_population:
        if subpopulation in outcomes:
            hist[outcomes.index(subpopulation)] += 1

    for i in range(len(hist)):
        if hist[i] == 0:
            continue
        for j in range(i + 1, len(hist)):
            if hist[j] == 0:
                continue
            hist[i] -= 1
            hist[j] -= 1
            mod *= 2
            mod %= mod
        if mod == 2:
            break

    for i in range(len(hist)):
        hist[i] = hist[i] * mod
        hist[i] %= mod

    return sum(hist) % (10**9 + 7)

initial_population = input().strip()
n = int(input().strip())
print(calculate_residues(initial_population, n))
