import math

def max_power_of_two(num):
    """Calculate the highest power of 2 that is less than or equal to num."""
    return int(math.log2(num))

def highest_set_bit(x, y):
    """Compute the highest set bit in x xor y."""
    if x == y:
        return 0
    else:
        return max(2**max_power_of_two(x & y), 2**max_power_of_two(x ^ y))

def calculate_function(array):
    """Compute the function f for the given segment [l, r]."""
    l, r = 0, len(array)
    result = 0
    while l < r:
        mid = int((l + r) / 2)
        temp_result = 0
        for i in range(mid):
            temp_result ^= abs(array[i])
            temp_result &= max_power_of_two(temp_result)
        result = temp_result
        l = mid + 1
    return result % 998244353

