import itertools

def is_possible(n, k, connections):
    connections.sort(key=lambda x: (x[0], x[1]))

    visited = [-1] * n
    colorings = itertools.product(range(1, k + 1), repeat=n)

    for coloring in colorings:
        valid = True
        for i, j in connections:
            if visited[i] == visited[j] or visited[i] + visited[j] in (0, 3):
                valid = False
                break

        if valid:
            for i in range(n):
                visited[i] = coloring[i]

            break

    if valid:
        return "Yes\n" + "\n".join(map(str, coloring))
    else:
        return "No"

