from heapq import heappush, heappop

def find_non_optimal_sum(face_values):
    if 1 in face_values:
        return -1  # Greedy algorithm can always represent any sum with coins of value 1

    min_heap = []
    total_sum = 0
    filled_coins_with_1 = False

    for val in face_values:
        if val == 1:
            if filled_coins_with_1:
                total_sum += 1
                heappush(min_heap, 1)
        else:
            heappush(min_heap, val)
            total_sum += val
            if val == 1:
                filled_coins_with_1 = True

    # Greedy algorithm may add coins from the heap until it exceeds the total sum
    while total_sum < 2 * min_heap[0]:
        total_sum += heappop(min_heap)

    return heappop(min_heap)

# Test cases
face_values1 = [25, 10, 5, 2, 1]
face_values2 = [4, 3, 1]

print(find_non_optimal_sum(face_values1))  # Expected output: -1
print(find_non_optimal_sum(face_values2))  # Expected output: 6
